package com.YouMissedThatOne;

import lombok.extern.slf4j.Slf4j;
import java.io.*;
import java.util.*;

import net.runelite.client.audio.AudioPlayer;


@Slf4j
public class SoundManager
{
    private final YouMissedThatOneConfig config;
    private final AudioPlayer audioPlayer;

    private final Map<File, byte[]> soundCache = new HashMap<>();

    public SoundManager(YouMissedThatOneConfig config, AudioPlayer audioPlayer)
    {
        this.config = config;
        this.audioPlayer = audioPlayer;
    }

    private byte[] loadSoundData(File file) throws IOException
    {
        return soundCache.computeIfAbsent(file, f ->
        {
            try (var is = new java.io.FileInputStream(f);
                 var buffer = new java.io.ByteArrayOutputStream())
            {
                byte[] data = new byte[1024];
                int nRead;
                while ((nRead = is.read(data)) != -1)
                {
                    buffer.write(data, 0, nRead);
                }
                return buffer.toByteArray();
            }
            catch (IOException e)
            {
                log.error("Failed to load sound {}", f, e);
                return null;
            }
        });
    }

    public void playCustomSound(File soundFile)
    {
        try
        {
            // Get the volume from config (0–100)
            int volumePercent = config.SoundSwapVolume();

            // Convert 0–100 volume to decibels for AudioPlayer
            float gainDb = (volumePercent > 0)
                    ? 20f * (float) Math.log10(volumePercent / 100.0f)
                    : -80f; // silent if volume = 0

            audioPlayer.play(soundFile, gainDb);
        }
        catch (Exception e)
        {
            log.error("Error playing custom sound: {}", e.getMessage());
        }
    }

    public void cleanup()
    {
        soundCache.clear();
    }
}

package com.YouMissedThatOne;

import net.runelite.client.config.*;

@ConfigGroup("YouMissedThatOne")
public interface YouMissedThatOneConfig extends Config
{


	@ConfigItem(
			keyName = "EnableOverlay",
			name = "Show ID overlay",
			description = "Shows held weapon item ID and current animation ID",
			position = 1
	)
	default boolean EnableOverLay()
	{
		return false;
	}

	@ConfigItem(
			keyName = "DeBugInfoOverlay",
			name = "Show debug info",
			description = "Additional info for debugging when overlay is shown",
			position = 2
	)
	default boolean DeBugInfoOverlay() {return false;}

	@ConfigItem(
			keyName = "EnableSoundSwap",
			name = "Enable sound swap",
			description = "Allows you to replace sound effects, similar to the Sound Swapper plugin." +
					"<br/> To replace a sound effect, add a .wav file to this plugin’s directory with the corresponding sound ID as the filename." +
					"<br/> For example, to replace sound ID \"1569\" with your custom sound, name the file \"1569.wav\"" +
					"<br/> Plugin directory location: %USERPROFILE%/.runelite/YouMissedThatOne",
			position = 3
	)
	default boolean EnableSoundSwap()
